/** Read only the bounded, uncompressed ZIP format generated by the website exporter. */
export const readWebsitePreviewArchive = async (archive:Blob):Promise<Record<string,string>> => {
  if(archive.size>64*1024*1024)throw new Error('This website preview exceeds the size limit.');
  const buffer=await archive.arrayBuffer(),view=new DataView(buffer),files:Record<string,string>=Object.create(null);let offset=0,count=0,total=0;
  while(offset+4<=view.byteLength&&view.getUint32(offset,true)===0x04034b50){
    if(offset+30>view.byteLength||view.getUint16(offset+8,true)!==0||view.getUint16(offset+6,true)&9)throw new Error('Unsupported website preview archive.');
    const size=view.getUint32(offset+18,true),nameLength=view.getUint16(offset+26,true),extraLength=view.getUint16(offset+28,true),start=offset+30+nameLength+extraLength,end=start+size;
    if(end>view.byteLength||++count>1000||(total+=size)>64*1024*1024)throw new Error('Invalid website preview archive.');
    const name=new TextDecoder('utf-8',{fatal:true}).decode(new Uint8Array(buffer,offset+30,nameLength));
    if(!name||name.startsWith('/')||name.includes('\\')||name.split('/').some(part=>!part||part==='.'||part==='..')||Object.hasOwn(files,name))throw new Error('Invalid website preview file.');
    let binary='';const bytes=new Uint8Array(buffer,start,size);for(let at=0;at<bytes.length;at+=32768)binary+=String.fromCharCode(...bytes.subarray(at,at+32768));files[name]=btoa(binary);offset=end;
  }
  if(!files['index.html']||offset+4>view.byteLength||view.getUint32(offset,true)!==0x02014b50)throw new Error('The website preview is incomplete.');
  return files;
};

/** A script-free loading surface, also used before the build and archive are ready. */
export const websitePreviewLoadingMarkup = `<style>
:root{color-scheme:light dark}body{margin:0;background:#f8f6fc;color:#272135;font:16px/1.6 system-ui,sans-serif}.website-preview-loading{position:fixed;inset:0;z-index:2;display:grid;place-content:center;justify-items:center;text-align:center;padding:2rem;background:inherit}.website-preview-loading h1{font-size:1.4rem;margin:1.25rem 0 .5rem}.website-preview-loading p{max-width:34rem;margin:.25rem 0;color:#635a72}.website-preview-spinner{width:2.5rem;height:2.5rem;border:.25rem solid #d9cfe9;border-top-color:#7954b0;border-radius:50%;animation:website-preview-spin .8s linear infinite}@keyframes website-preview-spin{to{transform:rotate(360deg)}}@media(prefers-color-scheme:dark){body{background:#201a2c;color:#f4eefc}.website-preview-loading p{color:#c3b8d5}.website-preview-spinner{border-color:#504060;border-top-color:#b99ae8}}@media(prefers-reduced-motion:reduce){.website-preview-spinner{animation:none;border-style:dotted}}
</style><main id="website-preview-loading" class="website-preview-loading" aria-busy="true"><span class="website-preview-spinner" aria-hidden="true"></span><h1>Opening website preview</h1><p id="website-preview-status" role="status" aria-live="polite">Preparing your saved pages and images…</p><p>This tab will show your website when it is ready.</p></main>`;
export const websitePreviewLoadingHtml = () => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Opening website preview</title></head><body>${websitePreviewLoadingMarkup}</body></html>`;

/** Trusted shell only: page content stays in a opaque-origin sandbox with only a nonce-authorized navigation bridge. */
export interface WebsitePreviewContext {
  websiteKey:string;revision:number;refreshChannel:string;editorUrl:string;pagePaths:Record<string,string>;
}
export const websitePreviewKey=(site:{workspaceId:string;id:string})=>'ubeeq.website-preview:'+site.workspaceId+':'+site.id;
/** Only revision information crosses tabs. The website content stays in its sandbox. */
export function notifyWebsitePreviewSaved(site:{workspaceId:string;id:string;revision:number}):void {
  if(typeof window==='undefined'||!Number.isSafeInteger(site.revision))return;
  const key=websitePreviewKey(site);
  try{const previous=Number(localStorage.getItem(key));if(previous>=site.revision)return;localStorage.setItem(key,String(site.revision));}catch{}
  try{const channel=new BroadcastChannel(key);channel.postMessage({type:'saved',revision:site.revision});channel.close();}catch{}
}
